"""
模型工厂类 - 支持消融研究的灵活模型创建
Model Factory - Flexible model creation for ablation studies
"""

from typing import Dict, Any, Type, Optional, List, Union
from abc import ABC, abstractmethod
import copy
import torch
import torch.nn as nn
from loguru import logger

# 导入不同的激活函数和组件
from torch.nn import ReLU, Tanh, Sigmoid, LeakyReLU, ELU, GELU
from torch.nn import Dropout, BatchNorm2d, GroupNorm
from torch.nn import MaxPool2d, AvgPool2d, AdaptiveAvgPool2d

# 假设已经实现了这些模块
