class ComponentFactory:
    """
    网络组件工厂类
    Network component factory class
    """

    # 激活函数映射
    ACTIVATION_FUNCTIONS = {
        'relu': ReLU,
        'tanh': Tanh,
        'sigmoid': Sigmoid,
        'leaky_relu': LeakyReLU,
        'elu': ELU,
        'gelu': GELU
    }

    # 归一化层映射
    NORMALIZATION_LAYERS = {
        'batch_norm': BatchNorm2d,
        'group_norm': GroupNorm,
        'lrn': LocalResponseNorm,  # 自定义的LRN层
    }

    # 池化层映射
    POOLING_LAYERS = {
        'max_pool': MaxPool2d,
        'avg_pool': AvgPool2d,
        'adaptive_avg_pool': AdaptiveAvgPool2d
    }

    @classmethod
    def create_activation(
        self, 
        activation_type: str, 
        **kwargs
    ) -> nn.Module:
        """
        创建激活函数
        Create activation function

        Args:
            activation_type: 激活函数类型
            **kwargs: 激活函数参数

        Returns:
            激活函数实例
        """
        if activation_type not in self.ACTIVATION_FUNCTIONS:
            raise ValueError(f"不支持的激活函数: {activation_type}")

        activation_class = self.ACTIVATION_FUNCTIONS[activation_type]

        # 处理特殊参数
        if activation_type == 'relu':
            return activation_class(inplace=kwargs.get('inplace', True))
        elif activation_type == 'leaky_relu':
            return activation_class(
                negative_slope=kwargs.get('negative_slope', 0.01),
                inplace=kwargs.get('inplace', True)
            )
        elif activation_type == 'elu':
            return activation_class(
                alpha=kwargs.get('alpha', 1.0),
                inplace=kwargs.get('inplace', True)
            )
        else:
            return activation_class()

    @classmethod
    def create_normalization(
        self, 
        norm_type: str, 
        num_features: int,
        **kwargs
    ) -> Optional[nn.Module]:
        """
        创建归一化层
        Create normalization layer

        Args:
            norm_type: 归一化类型
            num_features: 特征数量
            **kwargs: 归一化参数

        Returns:
            归一化层实例或None
        """
        if norm_type == 'none' or norm_type is None:
            return None

        if norm_type not in self.NORMALIZATION_LAYERS:
            raise ValueError(f"不支持的归一化类型: {norm_type}")

        norm_class = self.NORMALIZATION_LAYERS[norm_type]

        if norm_type == 'batch_norm':
            return norm_class(num_features)
        elif norm_type == 'group_norm':
            num_groups = kwargs.get('num_groups', 32)
            return norm_class(num_groups, num_features)
        elif norm_type == 'lrn':
            return norm_class(
                size=kwargs.get('size', 5),
                alpha=kwargs.get('alpha', 1e-4),
                beta=kwargs.get('beta', 0.75),
                k=kwargs.get('k', 2.0)
            )
        else:
            return norm_class()

    @classmethod
    def create_pooling(
        self, 
        pool_type: str, 
        **kwargs
    ) -> nn.Module:
        """
        创建池化层
        Create pooling layer

        Args:
            pool_type: 池化类型
            **kwargs: 池化参数

        Returns:
            池化层实例
        """
        if pool_type not in self.POOLING_LAYERS:
            raise ValueError(f"不支持的池化类型: {pool_type}")

        pool_class = self.POOLING_LAYERS[pool_type]

        if pool_type in ['max_pool', 'avg_pool']:
            return pool_class(
                kernel_size=kwargs.get('kernel_size', 3),
                stride=kwargs.get('stride', 2),
                padding=kwargs.get('padding', 0)
            )
        elif pool_type == 'adaptive_avg_pool':
            return pool_class(kwargs.get('output_size', (6, 6)))
        else:
            return pool_class(**kwargs)


class AblationModelFactory:
    """
    消融研究模型工厂类
    Ablation study model factory class
    """

    def __init__(self, base_config: Dict[str, Any]) -> None:
        """
        初始化消融模型工厂

        Args:
            base_config: 基础模型配置
        """
        self.base_config = copy.deepcopy(base_config)
        self.component_factory = ComponentFactory()

        logger.info("消融研究模型工厂初始化完成")

    def create_modified_model(
        self, 
        modifications: Dict[str, Any],
        model_name: Optional[str] = None
    ) -> 'BaseModel':
        """
        创建修改后的模型用于消融研究
        Create modified model for ablation study

        Args:
            modifications: 要修改的配置项
            model_name: 模型名称

        Returns:
            修改后的模型实例
        """
        # 深拷贝基础配置
        modified_config = copy.deepcopy(self.base_config)

        # 应用修改
        self._apply_modifications(modified_config, modifications)

        # 设置模型名称
        if model_name:
            modified_config['name'] = model_name

        # 创建模型
        model = self._create_model_from_config(modified_config)

        logger.info(f"创建消融研究模型: {model.model_name}")
        return model

    def _apply_modifications(
        self, 
        config: Dict[str, Any], 
        modifications: Dict[str, Any]
    ) -> None:
        """
        应用配置修改
        Apply configuration modifications

        Args:
            config: 目标配置字典
            modifications: 修改内容
        """
        for key, value in modifications.items():
            # 支持嵌套键，如 "model.activation.type"
            keys = key.split('.')
            current_dict = config

            # 导航到目标位置
            for k in keys[:-1]:
                if k not in current_dict:
                    current_dict[k] = {}
                current_dict = current_dict[k]

            # 设置值
            current_dict[keys[-1]] = value

    def _create_model_from_config(self, config: Dict[str, Any]) -> 'BaseModel':
        """
        根据配置创建模型
        Create model from configuration

        Args:
            config: 模型配置

        Returns:
            模型实例
        """
        model_type = config.get('type', 'AlexNet')

        if model_type == 'AlexNet':
            return AlexNet(config)
        elif model_type == 'AlexNetMultiGPU':
            return AlexNetMultiGPU(config)
        elif model_type == 'AlexNetMini':
            return AlexNetMini(config)
        else:
            raise ValueError(f"不支持的模型类型: {model_type}")

    def create_activation_ablation_models(self) -> Dict[str, 'BaseModel']:
        """
        创建激活函数消融研究模型
        Create activation function ablation study models

        Returns:
            激活函数消融模型字典
        """
        activation_types = ['relu', 'tanh', 'sigmoid', 'leaky_relu']
        models = {}

        for activation in activation_types:
            modifications = {
                'model.activation.type': activation
            }
            model_name = f"alexnet_{activation}"
            models[activation] = self.create_modified_model(
                modifications, model_name
            )

        logger.info(f"创建激活函数消融模型: {list(models.keys())}")
        return models

    def create_dropout_ablation_models(self) -> Dict[str, 'BaseModel']:
        """
        创建Dropout消融研究模型
        Create dropout ablation study models

        Returns:
            Dropout消融模型字典
        """
        dropout_configs = {
            'no_dropout': {
                'model.dropout.use_dropout': False
            },
            'light_dropout': {
                'model.dropout.use_dropout': True,
                'model.dropout.fc1_dropout_rate': 0.2,
                'model.dropout.fc2_dropout_rate': 0.2
            },
            'original_dropout': {
                'model.dropout.use_dropout': True,
                'model.dropout.fc1_dropout_rate': 0.5,
                'model.dropout.fc2_dropout_rate': 0.5
            },
            'heavy_dropout': {
                'model.dropout.use_dropout': True,
                'model.dropout.fc1_dropout_rate': 0.8,
                'model.dropout.fc2_dropout_rate': 0.8
            }
        }

        models = {}
        for config_name, modifications in dropout_configs.items():
            model_name = f"alexnet_{config_name}"
            models[config_name] = self.create_modified_model(
                modifications, model_name
            )

        logger.info(f"创建Dropout消融模型: {list(models.keys())}")
        return models

    def create_normalization_ablation_models(self) -> Dict[str, 'BaseModel']:
        """
        创建归一化消融研究模型
        Create normalization ablation study models

        Returns:
            归一化消融模型字典
        """
        norm_configs = {
            'with_lrn': {
                'model.normalization.use_lrn': True,
                'model.normalization.use_batch_norm': False
            },
            'no_lrn': {
                'model.normalization.use_lrn': False,
                'model.normalization.use_batch_norm': False
            },
            'batch_norm': {
                'model.normalization.use_lrn': False,
                'model.normalization.use_batch_norm': True
            }
        }

        models = {}
        for config_name, modifications in norm_configs.items():
            model_name = f"alexnet_{config_name}"
            models[config_name] = self.create_modified_model(
                modifications, model_name
            )

        logger.info(f"创建归一化消融模型: {list(models.keys())}")
        return models

    def create_depth_ablation_models(self) -> Dict[str, 'BaseModel']:
        """
        创建网络深度消融研究模型
        Create network depth ablation study models

        Returns:
            深度消融模型字典
        """
        depth_configs = {
            'original_5_conv': {
                'model.architecture.num_conv_layers': 5
            },
            'reduced_4_conv': {
                'model.architecture.num_conv_layers': 4,
                'model.architecture.conv_layers.conv5': None
            },
            'reduced_3_conv': {
                'model.architecture.num_conv_layers': 3,
                'model.architecture.conv_layers.conv4': None,
                'model.architecture.conv_layers.conv5': None
            }
        }

        models = {}
        for config_name, modifications in depth_configs.items():
            model_name = f"alexnet_{config_name}"
            models[config_name] = self.create_modified_model(
                modifications, model_name
            )

        logger.info(f"创建深度消融模型: {list(models.keys())}")
        return models

    def create_pooling_ablation_models(self) -> Dict[str, 'BaseModel']:
        """
        创建池化策略消融研究模型
        Create pooling strategy ablation study models

        Returns:
            池化消融模型字典
        """
        pooling_configs = {
            'overlapping_max_pool': {
                'model.architecture.pooling.type': 'max_pool',
                'model.architecture.pooling.kernel_size': 3,
                'model.architecture.pooling.stride': 2,
                'model.architecture.pooling.overlapping': True
            },
            'non_overlapping_max_pool': {
                'model.architecture.pooling.type': 'max_pool',
                'model.architecture.pooling.kernel_size': 2,
                'model.architecture.pooling.stride': 2,
                'model.architecture.pooling.overlapping': False
            },
            'average_pooling': {
                'model.architecture.pooling.type': 'avg_pool',
                'model.architecture.pooling.kernel_size': 3,
                'model.architecture.pooling.stride': 2
            }
        }

        models = {}
        for config_name, modifications in pooling_configs.items():
            model_name = f"alexnet_{config_name}"
            models[config_name] = self.create_modified_model(
                modifications, model_name
            )

        logger.info(f"创建池化消融模型: {list(models.keys())}")
        return models

    def create_all_ablation_models(self) -> Dict[str, Dict[str, 'BaseModel']]:
        """
        创建所有消融研究模型
        Create all ablation study models

        Returns:
            所有消融模型的嵌套字典
        """
        all_models = {
            'activation': self.create_activation_ablation_models(),
            'dropout': self.create_dropout_ablation_models(),
            'normalization': self.create_normalization_ablation_models(),
            'depth': self.create_depth_ablation_models(),
            'pooling': self.create_pooling_ablation_models()
        }

        # 统计总模型数量
        total_models = sum(len(models) for models in all_models.values())
        logger.info(f"创建所有消融研究模型完成，总数: {total_models}")

        return all_models


class ModelRegistry:
    """
    模型注册表 - 管理所有可用的模型类型
    Model registry - manages all available model types
    """

    def __init__(self) -> None:
        """初始化模型注册表"""
        self._models: Dict[str, Type['BaseModel']] = {}
        self._register_default_models()

    def _register_default_models(self) -> None:
        """注册默认模型"""
        self.register('AlexNet', AlexNet)
        self.register('AlexNetMultiGPU', AlexNetMultiGPU)
        self.register('AlexNetMini', AlexNetMini)

    def register(self, name: str, model_class: Type['BaseModel']) -> None:
        """
        注册新的模型类
        Register new model class

        Args:
            name: 模型名称
            model_class: 模型类
        """
        self._models[name] = model_class
        logger.info(f"注册模型类: {name}")

    def get_model_class(self, name: str) -> Type['BaseModel']:
        """
        获取模型类
        Get model class

        Args:
            name: 模型名称

        Returns:
            模型类
        """
        if name not in self._models:
            raise ValueError(f"未注册的模型类型: {name}")
        return self._models[name]

    def list_models(self) -> List[str]:
        """
        列出所有注册的模型
        List all registered models

        Returns:
            模型名称列表
        """
        return list(self._models.keys())

    def create_model(
        self, 
        model_type: str, 
        config: Dict[str, Any]
    ) -> 'BaseModel':
        """
        创建模型实例
        Create model instance

        Args:
            model_type: 模型类型
            config: 模型配置

        Returns:
            模型实例
        """
        model_class = self.get_model_class(model_type)
        return model_class(config)


# 全局模型注册表实例
model_registry = ModelRegistry()


def create_model_from_config(config: Dict[str, Any]) -> 'BaseModel':
    """
    从配置创建模型的便捷函数
    Convenience function to create model from config

    Args:
        config: 模型配置

    Returns:
        模型实例
    """
    model_type = config.get('type', 'AlexNet')
    return model_registry.create_model(model_type, config)


def create_ablation_study_models(
    base_config: Dict[str, Any],
    ablation_types: Optional[List[str]] = None
) -> Dict[str, Dict[str, 'BaseModel']]:
    """
    创建消融研究模型的便捷函数
    Convenience function to create ablation study models

    Args:
        base_config: 基础配置
        ablation_types: 要创建的消融类型列表

    Returns:
        消融模型字典
    """
    factory = AblationModelFactory(base_config)

    if ablation_types is None:
        return factory.create_all_ablation_models()

    ablation_models = {}
    for ablation_type in ablation_types:
        if ablation_type == 'activation':
            ablation_models['activation'] = factory.create_activation_ablation_models()
        elif ablation_type == 'dropout':
            ablation_models['dropout'] = factory.create_dropout_ablation_models()
        elif ablation_type == 'normalization':
            ablation_models['normalization'] = factory.create_normalization_ablation_models()
        elif ablation_type == 'depth':
            ablation_models['depth'] = factory.create_depth_ablation_models()
        elif ablation_type == 'pooling':
            ablation_models['pooling'] = factory.create_pooling_ablation_models()
        else:
            logger.warning(f"未知的消融类型: {ablation_type}")

    return ablation_models


